contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(caller != address(0));

        uint sent = amount;
        if (sent > address(this).balance) {
            sent = address(this).balance;
        }

        uint balBefore = address(c).balance;

        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted || address(c).balance == balBefore);
    }

    receive() external payable {}
}

